(()=>{
const solutions=[
{code:'01 / TALENT ACQUISITION',title:'讓對的人，看見加入你的理由。',intro:'招募卡關，可能出在職缺條件、曝光管道或面試流程。先找出候選人在哪一步離開，再決定 AI 該協助哪一段。',steps:[['職缺與雇主定位','釐清工作內容、條件與價值，改寫職缺頁與雇主品牌訊息。'],['建立招募流程','規劃來源紀錄、履歷整理、邀約提醒與面試追蹤；錄用判斷由人負責。'],['追蹤漏斗卡點','比較投遞、合格、面試與到職情況，逐步調整內容及管道。']],metric:'合格履歷率 ／ 面試到場率 ／ 招募週期',deliver:'交付：職缺文案、招募追蹤表、流程 SOP',need:5},
{code:'02 / BRAND & GROWTH',title:'從被看見，到讓人想選擇你。',intro:'品牌聲量要能連到生意。先說清楚服務誰、解決什麼，再把官網、內容、搜尋與詢問流程接起來。',steps:[['品牌定位與訊息','整理目標客群、差異與購買理由，統一品牌文案及視覺方向。'],['內容與曝光建構','規劃官網、SEO、社群與短影音，以 AI 輔助研究、初稿與內容整理。'],['連到詢問與成交','設定預約及詢問路徑、來源標記與追蹤指標，檢視內容帶來的實際行動。']],metric:'搜尋曝光 ／ 有效詢問 ／ 預約或成交轉換',deliver:'交付：品牌訊息架構、內容計畫、轉換追蹤表',need:6},
{code:'03 / OPERATIONS & AI',title:'把重複工作，變成可靠的流程。',intro:'先看清楚工作怎麼流動，再導入工具。從一個高頻、規則清楚的任務開始，避免把混亂直接自動化。',steps:[['盤點流程與資料','記錄現況、資料來源、責任人與例外狀況，找出耗時步驟。'],['建構單一流程試點','整合表單、資料庫、提醒與 AI 輔助整理，保留人工覆核。'],['驗收、訓練與交接','比較總工時、錯誤率與採用情況，完成操作文件和維護責任。']],metric:'總作業工時 ／ 錯誤率 ／ 團隊採用率',deliver:'交付：流程地圖、可操作試點、交接文件',need:1},
{code:'04 / FOUNDER ADVISORY',title:'讓老闆有方向，團隊有下一步。',intro:'當所有事情都回到老闆身上，先處理優先順序、決策權責與管理節奏，讓想法能被清楚承接。',steps:[['釐清目標與取捨','整理真正的經營問題、資源限制與 90 天內需要達成的結果。'],['建立責任與節奏','設定專案負責人、KPI、會議與回報方式，明確化需要升級決策的條件。'],['用數據推進修正','建立經營追蹤面板，檢視偏差、待決事項與下一步。']],metric:'關鍵任務完成率 ／ 決策等待時間 ／ KPI 進度',deliver:'交付：經營問題地圖、90 天計畫、專案追蹤板',need:0}
];
let selected=0;
function showSolution(i){selected=i;document.querySelectorAll('[data-solution]').forEach(b=>{let on=+b.dataset.solution===i;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});let d=solutions[i],p=document.getElementById('solution-panel');p.classList.remove('swap');p.innerHTML=`<div class="eyebrow">${d.code}</div><h3>${d.title}</h3><p>${d.intro}</p><div class="solution-steps">${d.steps.map((s,j)=>`<article class="solution-step"><span>0${j+1} —</span><h4>${s[0]}</h4><p>${s[1]}</p></article>`).join('')}</div><div class="solution-metric"><b>TRACKING</b>${d.metric}<br>${d.deliver}</div><a class="btn light" href="#brief" id="solution-cta">整理這項需求 <span>↗</span></a>`;p.setAttribute('aria-labelledby','solution-tab-'+i);requestAnimationFrame(()=>p.classList.add('swap'));document.getElementById('solution-cta').onclick=()=>{document.getElementById('need').selectedIndex=d.need}};
document.querySelectorAll('[data-solution]').forEach(b=>{b.onclick=()=>showSolution(+b.dataset.solution);b.onkeydown=e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();let n=e.key==='Home'?0:e.key==='End'?3:(selected+(e.key==='ArrowDown'?1:-1)+4)%4;showSolution(n);document.getElementById('solution-tab-'+n).focus()}}});document.querySelectorAll('[data-jump]').forEach(a=>a.onclick=()=>showSolution(+a.dataset.jump));showSolution(0);
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if('IntersectionObserver'in window&&!reduced){let observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-top,.positioning,.service,.case,.calc,.plan-panel,.brief-layout,.stat').forEach(el=>{el.classList.add('reveal');observer.observe(el)})}
const motion=document.createElement('button');motion.className='motion-toggle';motion.type='button';motion.setAttribute('aria-pressed',reduced?'true':'false');motion.textContent=reduced?'動畫已依系統減少':'暫停小動畫 Ⅱ';if(reduced)document.body.classList.add('motion-off');motion.onclick=()=>{const off=document.body.classList.toggle('motion-off');motion.setAttribute('aria-pressed',String(off));motion.textContent=off?'開啟小動畫 ▷':'暫停小動畫 Ⅱ'};document.querySelector('.footer-inner').appendChild(motion);
})();
